   172	static bt_status_t probe_notify(gatts_handle_t srv_handle,
   173	                                uint8_t *value, uint16_t length)
   174	{
   175	  if (!g_peer_connected || !g_notify_enabled)
   176	    {
   177	      printf("openvela_ble_probe: TX notification not subscribed\n");
   178	      return BT_STATUS_NOT_READY;
   179	    }
   180	
   181	  return bt_gatts_notify(srv_handle, &g_peer_addr, PROBE_TX_HANDLE,
   182	                         value, length);
   183	}
