   247	{
   248	  uint8_t response[21];
   249	  uint8_t *reply;
   250	  uint16_t reply_len;
   251	  uint32_t elapsed_ms;
   252	  uint32_t id_or_seq;
   253	  uint32_t seq;
   254	  bt_status_t status;
   255	
   256	  (void)attr_handle;
