   258	  if (offset != 0)
   259	    {
   260	      printf("openvela_ble_probe: long write is not supported\n");
   260	      printf("openvela_ble_probe: long write is not supported\n");
   261	      return 0;
   262	    }
   263	
   264	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   265	
   266	  if (length == 4 && memcmp(value, "PING", 4) == 0)
   267	    {
   268	      reply = g_pong;
   269	      reply_len = sizeof(g_pong);
   270	      printf("openvela_ble_probe: RX PING\n");
   271	    }
   272	  else if (length >= 1 && value[0] == 0x01)
   273	    {
   274	      if (length < 5)
   275	        {
   276	          printf("openvela_ble_probe: short binary PING length=%u\n",
   277	                 length);
   278	          return length;
   279	        }
   280	
   281	      id_or_seq = probe_get_le32(&value[1]);
   282	      response[0] = 0x81;
   283	      probe_put_le32(&response[1], id_or_seq);
   284	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
   285	             (unsigned long)id_or_seq);
   286	      status = probe_notify(srv_handle, response, 5);
   287	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
   288	      return length;
   289	    }
   290	  else if (length >= 1 && value[0] == 0x10)
   291	    {
   292	      if (length < 5)
   293	        {
   294	          printf("openvela_ble_probe: short START length=%u\n", length);
   295	          return length;
   296	        }
   297	
   298	      id_or_seq = probe_get_le32(&value[1]);
   299	      memset(&g_throughput, 0, sizeof(g_throughput));
   300	      g_throughput.active = true;
   301	      g_throughput.test_id = id_or_seq;
   302	
   303	      response[0] = 0x90;
   304	      probe_put_le32(&response[1], id_or_seq);
   305	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
   306	             (unsigned long)id_or_seq);
   307	      status = probe_notify(srv_handle, response, 5);
   308	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
   309	      return length;
   310	    }
   311	  else if (length >= 1 && value[0] == 0x11)
   312	    {
   313	      if (length < 5)
   314	        {
   315	          printf("openvela_ble_probe: short DATA length=%u\n", length);
   316	          return length;
   317	        }
   318	
   319	      if (!g_throughput.active)
   320	        {
   321	          printf("openvela_ble_probe: DATA without active test\n");
   322	          return length;
   323	        }
   324	
   325	      seq = probe_get_le32(&value[1]);
   326	      if (!g_throughput.timing)
   327	        {
   328	          if (clock_gettime(CLOCK_MONOTONIC,
   329	                            &g_throughput.started_at) == 0)
   330	            {
   331	              g_throughput.timing = true;
   332	            }
   333	          else
   334	            {
   335	              printf("openvela_ble_probe: monotonic clock failed\n");
   336	            }
   337	        }
   338	
   339	      g_throughput.frames++;
   340	      g_throughput.payload_bytes += length - 5;
   341	
   342	      if (!g_throughput.have_expected_seq)
   343	        {
   344	          g_throughput.expected_seq = seq + 1;
   345	          g_throughput.have_expected_seq = true;
   346	        }
   347	      else if (seq == g_throughput.expected_seq)
   348	        {
   349	          g_throughput.expected_seq++;
   350	        }
   351	      else if (seq > g_throughput.expected_seq)
   352	        {
   353	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
   354	          g_throughput.expected_seq = seq + 1;
   355	        }
   356	      else
   357	        {
   358	          g_throughput.missing_frames++;
   359	        }
   360	
   361	      return length;
   362	    }
   363	  else if (length >= 1 && value[0] == 0x12)
   364	    {
   365	      if (length < 5)
   366	        {
   367	          printf("openvela_ble_probe: short END length=%u\n", length);
   368	          return length;
   369	        }
   370	
   371	      id_or_seq = probe_get_le32(&value[1]);
   372	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
   373	        {
   374	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
   375	                 (unsigned long)id_or_seq);
   376	          return length;
   377	        }
   378	
   379	      elapsed_ms = g_throughput.timing ?
   380	                   probe_elapsed_ms(&g_throughput.started_at) : 0;
   381	      response[0] = 0x91;
   382	      probe_put_le32(&response[1], g_throughput.test_id);
   383	      probe_put_le32(&response[5], g_throughput.frames);
   384	      probe_put_le32(&response[9], g_throughput.payload_bytes);
   385	      probe_put_le32(&response[13], elapsed_ms);
   386	      probe_put_le32(&response[17], g_throughput.missing_frames);
   387	
   388	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
   389	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
   390	             (unsigned long)g_throughput.test_id,
   391	             (unsigned long)g_throughput.frames,
   392	             (unsigned long)g_throughput.payload_bytes,
   393	             (unsigned long)elapsed_ms,
   394	             (unsigned long)g_throughput.missing_frames);
   395	      status = probe_notify(srv_handle, response, sizeof(response));
   396	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
   397	      memset(&g_throughput, 0, sizeof(g_throughput));
   398	      return length;
   399	    }
   400	  else
   401	    {
   402	      reply = g_error;
   403	      reply_len = sizeof(g_error);
   404	      printf("openvela_ble_probe: RX unknown command\n");
   405	    }
   406	
   407	  status = probe_notify(srv_handle, reply, reply_len);
   408	  printf("openvela_ble_probe: TX notify status=%d\n", status);
   409	  return length;
   410	}
