   111	static int probe_wait_for_ble_startup(uint64_t target_ms)
   112	{
   113	  struct timespec now;
   114	  uint64_t uptime_ms;
   115	  uint64_t remaining_ms;
   116	  uint64_t sleep_ms;
   117	  bool delay_logged = false;
   118	
   119	  for (;;)
   120	    {
   121	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   122	        {
   123	          printf("openvela_ble_probe: failed to read system uptime\n");
   124	          return -1;
   125	        }
   126	
   127	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   128	                  (uint64_t)now.tv_nsec / 1000000u;
   129	      if (uptime_ms >= target_ms)
   130	        {
   131	          if (!delay_logged)
   132	            {
   133	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   134	                     "already satisfied\n",
   135	                     (unsigned long long)target_ms);
   136	            }
   137	
   138	          return 0;
   139	        }
   140	
   141	      remaining_ms = target_ms - uptime_ms;
   142	      if (!delay_logged)
   143	        {
   144	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   145	                 "for platform readiness (target=%llu ms)\n",
   146	                 (unsigned long long)remaining_ms,
   147	                 (unsigned long long)target_ms);
   148	          delay_logged = true;
   149	        }
   150	
   151	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
   152	      usleep((useconds_t)(sleep_ms * 1000u));
   153	    }
   154	}
