   215	static uint16_t probe_tx_cccd_written(gatts_handle_t srv_handle,
   216	                                      bt_address_t *addr,
   217	                                      uint16_t attr_handle,
   218	                                      const uint8_t *value,
   219	                                      uint16_t length,
   220	                                      uint16_t offset)
   221	{
   222	  uint16_t cccd;
   223	
   224	  (void)srv_handle;
   225	  (void)attr_handle;
   226	
   227	  if (offset != 0 || length < 2)
   228	    {
   229	      printf("openvela_ble_probe: invalid CCCD write\n");
   230	      return 0;
   231	    }
   232	
   233	  cccd = (uint16_t)value[0] | ((uint16_t)value[1] << 8);
   234	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   235	  g_notify_enabled = (cccd & GATT_CCC_NOTIFY) != 0;
   236	
   237	  printf("openvela_ble_probe: TX notify=%d\n", g_notify_enabled);
   238	  return length;
   239	}
