    87	            {
    88	              goto invalid;
    89	            }
    90	
    91	          value = value * 10u + (uint32_t)(*cursor - '0');
    92	          if (value > 15000u)
    93	            {
    94	              goto invalid;
    95	            }
    96	        }
    97	
    98	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
    99	        {
   100	          *target_ms = value;
   101	          return 0;
   102	        }
   103	    }
   104	
   105	invalid:
   106	  printf("Usage: openvela_ble_probe "
   107	         "[min_uptime_ms: 5000..15000, step 250]\n");
   108	  return -1;
   109	}
   110	
   111	static int probe_wait_for_ble_startup(uint64_t target_ms)
   112	{
   113	  struct timespec now;
   114	  uint64_t uptime_ms;
   115	  uint64_t remaining_ms;
   116	  uint64_t sleep_ms;
   117	  bool delay_logged = false;
   118	
   119	  for (;;)
   120	    {
   121	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   122	        {
   123	          printf("openvela_ble_probe: failed to read system uptime\n");
   124	          return -1;
   125	        }
   126	
   127	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   128	                  (uint64_t)now.tv_nsec / 1000000u;
   129	      if (uptime_ms >= target_ms)
   130	        {
   131	          if (!delay_logged)
   132	            {
   133	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   134	                     "already satisfied\n",
   135	                     (unsigned long long)target_ms);
   136	            }
   137	
   138	          return 0;
   139	        }
   140	
   141	      remaining_ms = target_ms - uptime_ms;
   142	      if (!delay_logged)
   143	        {
   144	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   145	                 "for platform readiness (target=%llu ms)\n",
   146	                 (unsigned long long)remaining_ms,
   147	                 (unsigned long long)target_ms);
   148	          delay_logged = true;
   149	        }
   150	
   151	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
   152	      usleep((useconds_t)(sleep_ms * 1000u));
   153	    }
   154	}
   155	
   156	static uint32_t probe_get_le32(const uint8_t *value)
   157	{
   158	  return (uint32_t)value[0] |
   159	         ((uint32_t)value[1] << 8) |
   160	         ((uint32_t)value[2] << 16) |
   161	         ((uint32_t)value[3] << 24);
   162	}
   163	
   164	static void probe_put_le32(uint8_t *value, uint32_t number)
   165	{
   166	  value[0] = (uint8_t)number;
   167	  value[1] = (uint8_t)(number >> 8);
   168	  value[2] = (uint8_t)(number >> 16);
   169	  value[3] = (uint8_t)(number >> 24);
   170	}
   171	
   172	static bt_status_t probe_notify(gatts_handle_t srv_handle,
   173	                                uint8_t *value, uint16_t length)
   174	{
   175	  if (!g_peer_connected || !g_notify_enabled)
   176	    {
   177	      printf("openvela_ble_probe: TX notification not subscribed\n");
   178	      return BT_STATUS_NOT_READY;
   179	    }
   180	
   181	  return bt_gatts_notify(srv_handle, &g_peer_addr, PROBE_TX_HANDLE,
   182	                         value, length);
   183	}
   184	
   185	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
   186	{
   187	  struct timespec ended_at;
   188	  int64_t seconds;
   189	  int64_t nanoseconds;
   190	  uint64_t milliseconds;
   191	
   192	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
   193	    {
   194	      return 0;
   195	    }
   196	
   197	  seconds = ended_at.tv_sec - started_at->tv_sec;
   198	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
   199	  if (nanoseconds < 0)
   200	    {
   201	      seconds--;
   202	      nanoseconds += 1000000000;
   203	    }
   204	
   205	  if (seconds < 0)
   206	    {
   207	      return 0;
   208	    }
   209	
   210	  milliseconds = (uint64_t)seconds * 1000 +
   211	                 (uint64_t)nanoseconds / 1000000;
   212	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
   213	}
   214	
   215	static uint16_t probe_tx_cccd_written(gatts_handle_t srv_handle,
   216	                                      bt_address_t *addr,
   217	                                      uint16_t attr_handle,
   218	                                      const uint8_t *value,
   219	                                      uint16_t length,
   220	                                      uint16_t offset)
   221	{
   222	  uint16_t cccd;
   223	
   224	  (void)srv_handle;
   225	  (void)attr_handle;
   226	
   227	  if (offset != 0 || length < 2)
   228	    {
   229	      printf("openvela_ble_probe: invalid CCCD write\n");
   230	      return 0;
   231	    }
   232	
   233	  cccd = (uint16_t)value[0] | ((uint16_t)value[1] << 8);
   234	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   235	  g_notify_enabled = (cccd & GATT_CCC_NOTIFY) != 0;
   236	
   237	  printf("openvela_ble_probe: TX notify=%d\n", g_notify_enabled);
   238	  return length;
   239	}
   240	
   241	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
   242	                                 bt_address_t *addr,
   243	                                 uint16_t attr_handle,
   244	                                 const uint8_t *value,
   245	                                 uint16_t length,
   246	                                 uint16_t offset)
   247	{
   248	  uint8_t response[21];
   249	  uint8_t *reply;
   250	  uint16_t reply_len;
   251	  uint32_t elapsed_ms;
   252	  uint32_t id_or_seq;
   253	  uint32_t seq;
   254	  bt_status_t status;
   255	
   256	  (void)attr_handle;
   257	
   258	  if (offset != 0)
   259	    {
   260	      printf("openvela_ble_probe: long write is not supported\n");
   260	      printf("openvela_ble_probe: long write is not supported\n");
   261	      return 0;
   262	    }
   263	
   264	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   265	
   266	  if (length == 4 && memcmp(value, "PING", 4) == 0)
   267	    {
   268	      reply = g_pong;
   269	      reply_len = sizeof(g_pong);
   270	      printf("openvela_ble_probe: RX PING\n");
   271	    }
   272	  else if (length >= 1 && value[0] == 0x01)
   273	    {
   274	      if (length < 5)
   275	        {
   276	          printf("openvela_ble_probe: short binary PING length=%u\n",
   277	                 length);
   278	          return length;
   279	        }
   280	
   281	      id_or_seq = probe_get_le32(&value[1]);
   282	      response[0] = 0x81;
   283	      probe_put_le32(&response[1], id_or_seq);
   284	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
   285	             (unsigned long)id_or_seq);
   286	      status = probe_notify(srv_handle, response, 5);
   287	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
   288	      return length;
   289	    }
   290	  else if (length >= 1 && value[0] == 0x10)
   291	    {
   292	      if (length < 5)
   293	        {
   294	          printf("openvela_ble_probe: short START length=%u\n", length);
   295	          return length;
   296	        }
   297	
   298	      id_or_seq = probe_get_le32(&value[1]);
   299	      memset(&g_throughput, 0, sizeof(g_throughput));
   300	      g_throughput.active = true;
   301	      g_throughput.test_id = id_or_seq;
   302	
   303	      response[0] = 0x90;
   304	      probe_put_le32(&response[1], id_or_seq);
   305	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
   306	             (unsigned long)id_or_seq);
   307	      status = probe_notify(srv_handle, response, 5);
   308	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
   309	      return length;
   310	    }
   311	  else if (length >= 1 && value[0] == 0x11)
   312	    {
   313	      if (length < 5)
   314	        {
   315	          printf("openvela_ble_probe: short DATA length=%u\n", length);
   316	          return length;
   317	        }
   318	
   319	      if (!g_throughput.active)
   320	        {
   321	          printf("openvela_ble_probe: DATA without active test\n");
   322	          return length;
   323	        }
   324	
   325	      seq = probe_get_le32(&value[1]);
   326	      if (!g_throughput.timing)
   327	        {
   328	          if (clock_gettime(CLOCK_MONOTONIC,
   329	                            &g_throughput.started_at) == 0)
   330	            {
   331	              g_throughput.timing = true;
   332	            }
   333	          else
   334	            {
   335	              printf("openvela_ble_probe: monotonic clock failed\n");
   336	            }
   337	        }
   338	
   339	      g_throughput.frames++;
   340	      g_throughput.payload_bytes += length - 5;
   341	
   342	      if (!g_throughput.have_expected_seq)
   343	        {
   344	          g_throughput.expected_seq = seq + 1;
   345	          g_throughput.have_expected_seq = true;
   346	        }
   347	      else if (seq == g_throughput.expected_seq)
   348	        {
   349	          g_throughput.expected_seq++;
   350	        }
   351	      else if (seq > g_throughput.expected_seq)
   352	        {
   353	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
   354	          g_throughput.expected_seq = seq + 1;
   355	        }
   356	      else
   357	        {
   358	          g_throughput.missing_frames++;
   359	        }
   360	
   361	      return length;
   362	    }
   363	  else if (length >= 1 && value[0] == 0x12)
   364	    {
   365	      if (length < 5)
   366	        {
   367	          printf("openvela_ble_probe: short END length=%u\n", length);
   368	          return length;
   369	        }
   370	
   371	      id_or_seq = probe_get_le32(&value[1]);
   372	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
   373	        {
   374	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
   375	                 (unsigned long)id_or_seq);
   376	          return length;
   377	        }
   378	
   379	      elapsed_ms = g_throughput.timing ?
   380	                   probe_elapsed_ms(&g_throughput.started_at) : 0;
   381	      response[0] = 0x91;
   382	      probe_put_le32(&response[1], g_throughput.test_id);
   383	      probe_put_le32(&response[5], g_throughput.frames);
   384	      probe_put_le32(&response[9], g_throughput.payload_bytes);
   385	      probe_put_le32(&response[13], elapsed_ms);
   386	      probe_put_le32(&response[17], g_throughput.missing_frames);
   387	
   388	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
   389	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
   390	             (unsigned long)g_throughput.test_id,
   391	             (unsigned long)g_throughput.frames,
   392	             (unsigned long)g_throughput.payload_bytes,
   393	             (unsigned long)elapsed_ms,
   394	             (unsigned long)g_throughput.missing_frames);
   395	      status = probe_notify(srv_handle, response, sizeof(response));
   396	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
   397	      memset(&g_throughput, 0, sizeof(g_throughput));
   398	      return length;
   399	    }
   400	  else
   401	    {
   402	      reply = g_error;
   403	      reply_len = sizeof(g_error);
   404	      printf("openvela_ble_probe: RX unknown command\n");
   405	    }
   406	
   407	  status = probe_notify(srv_handle, reply, reply_len);
   408	  printf("openvela_ble_probe: TX notify status=%d\n", status);
   409	  return length;
   410	}
