   185	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
   186	{
   187	  struct timespec ended_at;
   188	  int64_t seconds;
   189	  int64_t nanoseconds;
   190	  uint64_t milliseconds;
   191	
   192	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
   193	    {
   194	      return 0;
   195	    }
   196	
   197	  seconds = ended_at.tv_sec - started_at->tv_sec;
   198	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
   199	  if (nanoseconds < 0)
   200	    {
   201	      seconds--;
   202	      nanoseconds += 1000000000;
   203	    }
   204	
   205	  if (seconds < 0)
   206	    {
   207	      return 0;
   208	    }
   209	
   210	  milliseconds = (uint64_t)seconds * 1000 +
   211	                 (uint64_t)nanoseconds / 1000000;
   212	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
   213	}
