   619	static int start_advertising(void)
   620	{
   621	  ble_adv_params_t params;
   622	
   623	  if (g_advertiser != NULL)
   624	    {
   625	      return 0;
   626	    }
   627	
   628	  memset(&params, 0, sizeof(params));
   629	  params.adv_type = BT_LE_LEGACY_ADV_IND;
   630	  params.interval = 320;
   631	  params.duration = 0;
   632	  params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
   633	  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
   634	
   635	  if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   636	    {
   637	      g_adv_data = advertiser_data_new();
   638	      g_scan_rsp_data = advertiser_data_new();
   639	      if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   640	        {
   641	          printf("openvela_ble_probe: advertiser_data_new failed\n");
   642	          return -1;
   643	        }
   644	
   645	      advertiser_data_set_flags(g_adv_data,
   646	                                BT_AD_FLAG_GENERAL_DISCOVERABLE |
   647	                                BT_AD_FLAG_BREDR_NOT_SUPPORT);
   648	      advertiser_data_set_name(g_scan_rsp_data, "ov_ble_probe");
   649	
   650	      g_adv_payload = advertiser_data_build(g_adv_data,
   651	                                            &g_adv_payload_len);
   652	      g_scan_rsp_payload = advertiser_data_build(g_scan_rsp_data,
   653	                                                 &g_scan_rsp_payload_len);
   654	      if (g_adv_payload == NULL || g_scan_rsp_payload == NULL)
   655	        {
   656	          printf("openvela_ble_probe: advertiser_data_build failed\n");
   657	          return -1;
   658	        }
   659	    }
   660	
   661	  g_advertiser = bt_le_start_advertising(g_instance, &params,
   662	                                         g_adv_payload, g_adv_payload_len,
   663	                                         g_scan_rsp_payload,
   664	                                         g_scan_rsp_payload_len,
   665	                                         &g_advertiser_callbacks);
   666	  if (g_advertiser == NULL)
   667	    {
   668	      printf("openvela_ble_probe: bt_le_start_advertising failed\n");
   669	      return -1;
   670	    }
   671	
   672	  printf("openvela_ble_probe: advertising as ov_ble_probe\n");
   673	  return 0;
   674	}
