    70	static int probe_parse_startup_uptime(int argc, char *argv[],
    71	                                      uint64_t *target_ms)
    72	{
    73	  const char *cursor;
    74	  uint32_t value = 0;
    75	
    76	  if (argc == 1)
    77	    {
    78	      *target_ms = MIN_BLE_STARTUP_UPTIME_MS;
    79	      return 0;
    80	    }
    81	
    82	  if (argc == 2 && argv[1][0] != '\0')
    83	    {
    84	      for (cursor = argv[1]; *cursor != '\0'; cursor++)
    85	        {
    86	          if (*cursor < '0' || *cursor > '9')
    87	            {
    88	              goto invalid;
    89	            }
    90	
    91	          value = value * 10u + (uint32_t)(*cursor - '0');
    92	          if (value > 15000u)
    93	            {
    94	              goto invalid;
    95	            }
    96	        }
    97	
    98	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
    99	        {
   100	          *target_ms = value;
   101	          return 0;
   102	        }
   103	    }
   104	
   105	invalid:
   106	  printf("Usage: openvela_ble_probe "
   107	         "[min_uptime_ms: 5000..15000, step 250]\n");
   108	  return -1;
   109	}
