   676	int main(int argc, char *argv[])
   677	{
   678	  bt_status_t status;
   679	  uint64_t startup_target_ms;
   680	
   681	  if (probe_parse_startup_uptime(argc, argv, &startup_target_ms) < 0)
   682	    {
   683	      return 1;
   684	    }
   685	
   686	  if (probe_wait_for_ble_startup(startup_target_ms) < 0)
   687	    {
   688	      return 1;
   689	    }
   690	
   691	  sem_init(&g_ble_on_sem, 0, 0);
   692	
   693	  g_instance = bluetooth_create_instance();
   694	  if (g_instance == NULL)
   695	    {
   696	      printf("openvela_ble_probe: bluetooth_create_instance failed\n");
   697	      return 1;
   698	    }
   699	
   700	  if (bt_adapter_register_callback(g_instance, &g_adapter_callbacks) == NULL)
   701	    {
   702	      printf("openvela_ble_probe: callback registration failed\n");
   703	      return 1;
   704	    }
   705	
   706	  status = bt_adapter_enable_le(g_instance);
   707	  if (status != BT_STATUS_SUCCESS && status != BT_STATUS_DONE)
   708	    {
   709	      printf("openvela_ble_probe: bt_adapter_enable_le failed:%d\n",
   710	             status);
   711	      return 1;
   712	    }
   713	
   714	  if (bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_BLE_ON &&
   715	      bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_ON)
   716	    {
   717	      printf("openvela_ble_probe: waiting for BLE adapter\n");
   718	      sem_wait(&g_ble_on_sem);
   719	    }
   720	
   721	  if (init_gatt_service() < 0)
   722	    {
   723	      return 1;
   724	    }
   725	
   726	  printf("openvela_ble_probe: delaying advertising 100 ms after GATT "
   727	         "table setup\n");
   728	  usleep(100000);
   729	
   730	  if (start_advertising() < 0)
   731	    {
   732	      return 1;
   733	    }
   734	
   735	  for (;;)
   736	    {
   737	      usleep(100000);
   738	
   739	      if (g_peer_connected && g_phy_read_pending &&
   740	          !g_phy_read_requested)
   741	        {
   742	          g_phy_read_pending = false;
   743	          g_phy_read_requested = true;
   744	          status = bt_gatts_read_phy(g_service_handle, &g_peer_addr);
   745	          printf("openvela_ble_probe: PHY read request status=%d\n",
   746	                 status);
   747	
   748	          if (status == BT_STATUS_SUCCESS)
   749	            {
   750	              g_phy_update_pending = true;
   751	            }
   752	
   753	          continue;
   754	        }
   755	
   756	      if (g_peer_connected && g_phy_update_pending &&
   757	          !g_phy_update_requested)
   758	        {
   759	          g_phy_update_pending = false;
   760	          g_phy_update_requested = true;
   761	          status = bt_gatts_update_phy(g_service_handle, &g_peer_addr,
   762	                                       BT_LE_2M_PHY, BT_LE_2M_PHY);
   763	          printf("openvela_ble_probe: PHY 2M request status=%d\n",
   764	                 status);
   765	        }
   766	    }
   767	}

