   546	    if (test_time <= 0)
   547	        return CMD_INVALID_OPT;
   548	
   549	    if (!g_custom_handle) {
   550	        PRINT("please register and start custom service at first !");
   551	        return CMD_ERROR;
   552	    }
   553	
   554	    gatts_device_t* device = find_gatts_device(&addr);
   555	    if (!device) {
   556	        PRINT_ADDR("device:%s is not connected", &addr);
   557	        return CMD_INVALID_ADDR;
   558	    }
   559	
   560	    if (!cccd_enable) {
   561	        PRINT("please enable cccd of custom tx char at first !");
   562	        return CMD_ERROR;
   563	    }
   564	
   565	    uint32_t notify_length = device->gatt_mtu;
   566	    uint8_t* payload = (uint8_t*)malloc(sizeof(uint8_t) * notify_length);
   567	    if (!payload) {
   568	        PRINT("notify payload malloc failed");
   569	        return CMD_ERROR;
   570	    }
   571	
   572	    int32_t run_time = 0;
   573	    uint32_t notify_count = 0;
   574	    uint32_t bit_rate = 0;
   575	    struct timespec start_ts;
   576	
   577	    clock_gettime(CLOCK_BOOTTIME, &start_ts);
   578	    throughtput_cursor = 0;
   579	
   580	    PRINT("gatts notify throughput test start, mtu = %" PRIu32 ", time = %" PRId32 "s.", notify_length, test_time);
   581	    while (1) {
   582	        struct timespec current_ts;
   583	        clock_gettime(CLOCK_BOOTTIME, &current_ts);
   584	
   585	        if (run_time < (current_ts.tv_sec - start_ts.tv_sec)) {
   586	            run_time = (current_ts.tv_sec - start_ts.tv_sec);
   587	            bit_rate = notify_length * notify_count / run_time;
   588	            PRINT("gatts notify Bit rate = %" PRIu32 " Byte/s, = %" PRIu32 " bit/s, time = %" PRId32 "s.", bit_rate, bit_rate << 3, run_time);
   589	        }
   590	
   591	        device = find_gatts_device(&addr);
   592	        if (!device || run_time >= test_time) {
   593	            break;
   594	        }
   595	
   596	        if (throughtput_cursor >= THROUGHTPUT_HORIZON) {
   597	            usleep(500);
   598	            continue;
   599	        }
   600	
   601	        memset(payload, notify_count & 0xFF, notify_length);
   602	        int ret = bt_gatts_notify(g_custom_handle, &addr, IOT_SERVICE_TX_CHR_ID, payload, notify_length);
   603	        if (ret != BT_STATUS_SUCCESS) {
   604	            PRINT("notify failed, ret: %d.", ret);
   605	            break;
   606	        }
   607	        throughtput_cursor++;
   608	        notify_count++;
   609	    }
   610	    free(payload);
   611	
   612	    if (run_time <= 0) {
   613	        PRINT("gatts notify throughput test failed due to an unexpected interruption!");
   614	        return CMD_ERROR;
   615	    }
