   586	static bt_status_t if_gatts_add_attr_table(void* srv_handle, gatt_srv_db_t* srv_db)
   587	{
   588	    gatts_service_t* service = srv_handle;
   589	
   590	    CHECK_ENABLED();
   591	    CHECK_SERVICE_VALID(g_gatts_manager.services, service);
   592	
   593	    service_table_t* svc_table = find_service_table_by_id(service, srv_db->attr_db[0].handle + service->srv_id);
   594	    if (svc_table)
   595	        return BT_STATUS_PARM_INVALID;
   596	
   597	    svc_table = service_table_new(srv_db->attr_num);
   598	    if (svc_table == NULL)
   599	        return BT_STATUS_NOMEM;
   600	
   601	    gatt_element_t* elements = svc_table->elements;
   602	    gatt_attr_db_t* attr_inst = srv_db->attr_db;
   603	    for (int i = 0; i < srv_db->attr_num; i++, elements++, attr_inst++) {
   604	
   605	        elements->handle = service->srv_id + attr_inst->handle;
   606	        elements->type = attr_inst->type;
   607	        elements->properties = attr_inst->properties;
   608	        elements->permissions = attr_inst->permissions;
   609	        elements->rsp_type = attr_inst->rsp_type;
   610	        elements->read_cb = attr_inst->read_cb;
   611	        elements->write_cb = attr_inst->write_cb;
   612	        elements->attr_length = attr_inst->attr_length;
   613	        elements->attr_data = NULL;
   614	        if (elements->rsp_type == ATTR_AUTO_RSP && elements->attr_length) {
   615	            elements->attr_data = malloc(elements->attr_length);
   616	            memcpy(elements->attr_data, attr_inst->attr_value, elements->attr_length);
   617	        }
   618	
   619	        memcpy(&elements->uuid, &attr_inst->uuid, sizeof(bt_uuid_t));
   620	    }
   621	    svc_table->start_handle = svc_table->elements[0].handle;
   622	    svc_table->end_handle = svc_table->elements[svc_table->element_size - 1].handle;
   623	
   624	    bt_status_t status = bt_sal_gatt_server_add_elements(svc_table->elements, svc_table->element_size);
   625	    if (status != BT_STATUS_SUCCESS) {
   626	        service_table_delete(svc_table);
   627	        return status;
   628	    }
   629	
   630	    bt_list_add_tail(service->tables, svc_table);
   835	}
