440	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
441	                                 bt_address_t *addr,
442	                                 uint16_t attr_handle,
443	                                 const uint8_t *value,
444	                                 uint16_t length,
445	                                 uint16_t offset)
446	{
447	  struct probe_rx_slot_s *slot;
448	
449	  (void)srv_handle;
450	  (void)attr_handle;
451	
452	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
453	    {
454	      __atomic_fetch_add(&g_rx_dropped, 1, __ATOMIC_RELAXED);
455	      printf("openvela_ble_probe: invalid RX frame offset=%u length=%u\n",
456	             offset, length);
457	      return 0;
458	    }
459	
460	  if (pthread_mutex_trylock(&g_state_lock) != 0)
461	    {
462	      __atomic_fetch_add(&g_rx_dropped, 1, __ATOMIC_RELAXED);
463	      return length;
464	    }
465	
466	  if (g_rx_count >= PROBE_RX_QUEUE_DEPTH)
467	    {
468	      pthread_mutex_unlock(&g_state_lock);
469	      __atomic_fetch_add(&g_rx_dropped, 1, __ATOMIC_RELAXED);
470	      return length;
471	    }
472	
473	  slot = &g_rx_queue[g_rx_head];
474	  memcpy(&slot->addr, addr, sizeof(slot->addr));
475	  slot->connection_generation = g_connection_generation;
476	  slot->length = length;
477	  slot->offset = offset;
478	  memcpy(slot->value, value, length);
479	  g_rx_head = (g_rx_head + 1) % PROBE_RX_QUEUE_DEPTH;
480	  g_rx_count++;
481	  pthread_mutex_unlock(&g_state_lock);
482	
483	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
484	  sem_post(&g_rx_sem);
485	  return length;
486	}
