488	static void *probe_communication_thread(void *arg)
489	{
490	  struct probe_rx_slot_s slot;
491	  bt_address_t peer_addr;
492	  uint32_t generation;
493	  uint32_t active_generation = 0;
494	  bool connected;
495	  bool have_slot;
496	
497	  (void)arg;
498	
499	  for (;;)
500	    {
501	      while (sem_wait(&g_rx_sem) < 0 && errno == EINTR)
502	        {
503	        }
504	
505	      pthread_mutex_lock(&g_state_lock);
506	      generation = g_connection_generation;
507	      connected = g_peer_connected;
508	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
509	      have_slot = g_rx_count > 0;
510	      if (have_slot)
511	        {
512	          memcpy(&slot, &g_rx_queue[g_rx_tail], sizeof(slot));
513	          g_rx_tail = (g_rx_tail + 1) % PROBE_RX_QUEUE_DEPTH;
514	          g_rx_count--;
515	        }
516	      pthread_mutex_unlock(&g_state_lock);
517	
518	      if (generation != active_generation)
519	        {
520	          memset(&g_throughput, 0, sizeof(g_throughput));
521	          active_generation = generation;
522	        }
523	
524	      if (!have_slot)
525	        {
526	          continue;
527	        }
528	
529	      if (!connected || slot.connection_generation != generation ||
530	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
531	        {
532	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
533	          continue;
534	        }
535	
536	      probe_process_frame(g_service_handle, slot.value, slot.length);
537	    }
538	
539	  return NULL;
540	}
