442	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
443	                                 bt_address_t *addr,
444	                                 uint16_t attr_handle,
445	                                 const uint8_t *value,
446	                                 uint16_t length,
447	                                 uint16_t offset)
448	{
449	  struct probe_rx_slot_s *slot;
450	
451	  (void)srv_handle;
452	  (void)attr_handle;
453	
454	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
455	    {
456	      __atomic_fetch_add(&g_rx_dropped, 1, __ATOMIC_RELAXED);
457	      return 0;
458	    }
459	
460	  if (pthread_mutex_trylock(&g_state_lock) != 0)
461	    {
462	      __atomic_fetch_add(&g_rx_dropped, 1, __ATOMIC_RELAXED);
463	      return length;
464	    }
465	
466	  if (g_rx_count >= PROBE_RX_QUEUE_DEPTH)
467	    {
468	      pthread_mutex_unlock(&g_state_lock);
469	      __atomic_fetch_add(&g_rx_dropped, 1, __ATOMIC_RELAXED);
470	      return length;
471	    }
472	
473	  slot = &g_rx_queue[g_rx_head];
474	  memcpy(&slot->addr, addr, sizeof(slot->addr));
475	  slot->connection_generation = g_connection_generation;
476	  slot->length = length;
477	  slot->offset = offset;
478	  memcpy(slot->value, value, length);
479	  g_rx_head = (g_rx_head + 1) % PROBE_RX_QUEUE_DEPTH;
480	  g_rx_count++;
481	  pthread_mutex_unlock(&g_state_lock);
482	
483	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
484	  sem_post(&g_rx_sem);
485	  return length;
486	}
487	
488	static void *probe_communication_thread(void *arg)
489	{
490	  struct probe_rx_slot_s slot;
500	  for (;;)
501	    {
502	      do
503	        {
504	          wait_status = sem_wait(&g_rx_sem);
505	        }
506	      while (wait_status < 0 && errno == EINTR);
507	
508	      if (wait_status < 0)
509	        {
510	          continue;
511	        }
512	
513	      pthread_mutex_lock(&g_state_lock);
514	      generation = g_connection_generation;
515	      connected = g_peer_connected;
516	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
517	      have_slot = g_rx_count > 0;
518	      if (have_slot)
519	        {
520	          memcpy(&slot, &g_rx_queue[g_rx_tail], sizeof(slot));
521	          g_rx_tail = (g_rx_tail + 1) % PROBE_RX_QUEUE_DEPTH;
522	          g_rx_count--;
523	        }
524	      pthread_mutex_unlock(&g_state_lock);
525	
526	      if (generation != active_generation)
527	        {
528	          memset(&g_throughput, 0, sizeof(g_throughput));
529	          active_generation = generation;
530	        }
531	
532	      if (!have_slot)
533	        {
534	          continue;
535	        }
536	
537	      if (!connected || slot.connection_generation != generation ||
538	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
539	        {
540	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
541	          continue;
542	        }
543	
544	      probe_process_frame(g_service_handle, slot.value, slot.length);
545	    }
546	
547	  return NULL;
548	}
