242	static void gatts_process_message(void* data)
243	{
244	    gatts_service_t* service;
245	    gatts_msg_t* msg = (gatts_msg_t*)data;
246	
247	    pthread_mutex_lock(&g_gatts_manager.device_lock);
248	    if (!g_gatts_manager.started)
249	        goto end;
250	
251	    switch (msg->event) {
252	    case GATTS_EVENT_ATTR_TABLE_ADDED: {
253	        service = find_gatts_service_by_id(msg->param.added.element_id);
254	        if (service) {
255	            GATT_CBACK(service->callbacks, on_attr_table_added, service, msg->param.added.status, msg->param.added.element_id ^ service->srv_id);
256	        }
257	    } break;
258	    case GATTS_EVENT_ATTR_TABLE_REMOVED: {
259	        service = find_gatts_service_by_id(msg->param.removed.element_id);
260	        if (service) {
261	            service_table_t* svc_table = find_service_table_by_id(service, msg->param.removed.element_id);
262	            if (svc_table) {
263	                bt_list_remove(service->tables, svc_table);
264	            }
265	            GATT_CBACK(service->callbacks, on_attr_table_removed, service, msg->param.removed.status, msg->param.removed.element_id ^ service->srv_id);
266	        }
267	    } break;
268	    case GATTS_EVENT_CONNECT_CHANGE: {
269	        profile_connection_state_t connect_state = msg->param.connect_change.state;
270	        BT_ADDR_LOG("GATTS-CONNECTION-STATE-EVENT from:%s, state:%d", &msg->param.connect_change.addr, connect_state);
271	        if (connect_state == PROFILE_STATE_CONNECTED) {
272	            GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_connected, &msg->param.connect_change.addr);
273	        } else if (connect_state == PROFILE_STATE_DISCONNECTED) {
274	            GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_disconnected, &msg->param.connect_change.addr);
275	        }
276	    } break;
277	    case GATTS_EVENT_READ_REQUEST: {
278	        service = find_gatts_service_by_id(msg->param.read.element_id);
279	        if (!service)
280	            break;
281	
282	        gatt_element_t* element = find_service_element_by_id(service, msg->param.read.element_id);
283	        if (!element)
284	            break;
285	
286	        if (element->rsp_type == ATTR_AUTO_RSP || element->rsp_type == ATTR_AUTO_RSP_CCC_READ) {
287	            bt_sal_gatt_server_send_response(PRIMARY_ADAPTER, &msg->param.read.addr, msg->param.read.request_id, element->attr_data, element->attr_length);
288	        } else if (element->read_cb) {
289	            element->read_cb(service, &msg->param.read.addr, msg->param.read.element_id ^ service->srv_id, msg->param.read.request_id);
290	        }
291	    } break;
292	    case GATTS_EVENT_WRITE_REQUEST: {
293	        service = find_gatts_service_by_id(msg->param.write.element_id);
294	        if (!service)
295	            break;
296	
297	        gatt_element_t* element = find_service_element_by_id(service, msg->param.write.element_id);
298	        if (!element)
299	            break;
300	
301	        bt_sal_gatt_server_send_response(PRIMARY_ADAPTER, &msg->param.write.addr, msg->param.write.request_id, NULL, 0);
302	        if (element->rsp_type == ATTR_AUTO_RSP) {
303	            if (element->attr_data) {
304	                msg->param.write.length = MIN(element->attr_length, msg->param.write.length);
305	                memcpy(element->attr_data, msg->param.write.value, msg->param.write.length);
306	            }
307	        } else if (element->write_cb) {
308	            element->write_cb(service, &msg->param.write.addr, msg->param.write.element_id ^ service->srv_id, msg->param.write.value,
309	                msg->param.write.length, msg->param.write.offset);
310	        }
311	    } break;
312	    case GATTS_EVENT_MTU_CHANGE:
313	        GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_mtu_changed, &msg->param.mtu_change.addr, msg->param.mtu_change.mtu);
314	        break;
315	    case GATTS_EVENT_CHANGE_SEND: {
316	        service = find_gatts_service_by_id(msg->param.change_send.element_id);
317	        if (service) {
318	            GATT_CBACK(service->callbacks, on_notify_complete, service, &msg->param.change_send.addr, msg->param.change_send.status,
319	                msg->param.change_send.element_id ^ service->srv_id);
320	        }
321	    } break;
322	    case GATTS_EVENT_PHY_READ: {
323	        gatts_op_t* operation = gatts_pendops_execute_out(&g_gatts_manager, GATTS_REQ_READ_PHY);
324	        if (operation) {
325	            service = (gatts_service_t*)operation->param.phy.srv_handle;
326	            GATT_CBACK(service->callbacks, on_phy_read, service, &msg->param.phy.addr, msg->param.phy.tx_phy, msg->param.phy.rx_phy);
327	            bt_list_remove(g_gatts_manager.pend_ops, operation);
328	        }
329	    } break;
330	    case GATTS_EVENT_PHY_UPDATE: {
331	        if (msg->param.phy.status == GATT_STATUS_SUCCESS) {
332	            GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_phy_updated, &msg->param.phy.addr, msg->param.phy.status,
333	                msg->param.phy.tx_phy, msg->param.phy.rx_phy);
334	        } else {
335	            gatts_op_t* operation = gatts_pendops_execute_out(&g_gatts_manager, GATTS_REQ_UPDATE_PHY);
336	            if (operation) {
337	                service = (gatts_service_t*)operation->param.phy.srv_handle;
338	                GATT_CBACK(service->callbacks, on_phy_updated, service, &msg->param.phy.addr, msg->param.phy.status, msg->param.phy.tx_phy,
339	                    msg->param.phy.rx_phy);
340	                bt_list_remove(g_gatts_manager.pend_ops, operation);
341	            }
342	        }
343	    } break;
344	    case GATTS_EVENT_CONN_PARAM_CHANGE:
345	        GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_conn_param_changed, &msg->param.conn_param.addr,
346	            msg->param.conn_param.interval, msg->param.conn_param.latency, msg->param.conn_param.timeout);
347	        break;
348	    default: {
349	
350	    } break;
351	    }
352	
353	end:
354	    pthread_mutex_unlock(&g_gatts_manager.device_lock);
355	    gatts_msg_destory(msg);
356	}
