298	static ssize_t write_value(struct bt_conn* conn, const struct bt_gatt_attr* attr,
299	    const void* buf, uint16_t len, uint16_t offset, uint8_t flags)
300	{
301	    bt_address_t addr;
302	    gatt_element_t* element;
303	    uint32_t request_id;
304	    int ret;
305	
306	    if (!attr || !attr->user_data) {
307	        BT_LOGE("%s, user_data is NULL", __func__);
308	        return BT_GATT_ERR(BT_ATT_ERR_UNLIKELY);
309	    }
310	
311	    element = (gatt_element_t*)attr->user_data;
312	
313	    if (flags & GATT_WRITE_FLAGS_RELIABLE_WRITE) {
314	        BT_LOGE("%s, reliable write is not supported", __func__);
315	        return BT_GATT_ERR(BT_ATT_ERR_UNLIKELY);
316	    }
317	
318	    if (flags & BT_GATT_WRITE_FLAG_CMD) {
319	        request_id = REQUEST_ID_NORSP;
320	        ret = len;
321	    } else {
322	        request_id = MAKE_REQUEST_ID(element->handle, GATT_OPS_WRITE_REQUEST);
323	        ret = -EINPROGRESS;
324	    }
325	
326	    bt_sal_get_remote_address(conn, &addr);
327	
328	    if_gatts_on_received_element_write_request(&addr, request_id, element->handle, (uint8_t*)buf, offset, len);
329	
330	    return ret;
331	}
