334	{
335	    struct bt_gatt_attr* attr = &server_db[attr_count];
336	
337	    if (attr_count >= CONFIG_GATT_SERVER_MAX_ATTRIBUTES) {
338	        BT_LOGE("%s, server_db is full", __func__);
339	        return NULL;
340	    }
341	
342	    const union uuid* u = CONTAINER_OF(pattern->uuid, union uuid, uuid);
343	    size_t uuid_size = (u->uuid.type == BT_UUID_TYPE_16) ? sizeof(u->u16) : sizeof(u->u128);
344	
345	    memcpy(attr, pattern, sizeof(*attr));
790	    struct _bt_gatt_ccc* ccc;
791	    gatt_element_t* element;
792	    uint16_t value;
793	    ssize_t ret;
794	    uint8_t index;
795	
796	    ret = bt_gatt_attr_write_ccc(conn, attr, buf, len, offset, flags);
797	
798	    if (ret < 0)
799	        return ret;
800	
801	    ccc = (struct _bt_gatt_ccc*)attr->user_data;
802	
803	    wrapper = CONTAINER_OF(ccc, struct gatt_ccc_wrapper, ccc);
804	    element = wrapper->element;
805	
806	    index = bt_conn_index(conn);
807	    if (index >= CONFIG_BT_MAX_CONN) {
808	        BT_LOGE("%s, invalid conn index = %u", __func__, index);
809	        return -EINVAL;
810	    }
811	
812	    value = ccc->cfg[index].value;
813	
814	    bt_sal_get_remote_address(conn, &addr);
815	
816	    if_gatts_on_received_element_write_request(&addr, GATT_OPS_WRITE_REQUEST,
817	        element->handle, (uint8_t*)&value, 0, sizeof(value));
818	
819	    // framework response
820	    return -EINPROGRESS;
821	}
