229	static gatts_op_t* gatts_pendops_execute_out(gatts_manager_t* manager, gatts_request_t request)
230	{
231	    bt_list_node_t* node;
232	    bt_list_t* list = manager->pend_ops;
233	    for (node = bt_list_head(list); node != NULL; node = bt_list_next(list, node)) {
234	        gatts_op_t* operation = (gatts_op_t*)bt_list_node(node);
235	        if (operation->request == request) {
236	            return operation;
237	        }
238	    }
239	    return NULL;
240	}
