  2457	static uint8_t att_exec_write_rsp(struct bt_att_chan *chan, uint8_t flags)
  2458	{
  2459		struct net_buf *buf;
  2460		uint8_t err = 0U;
  2461	
  2462		/* The following code will iterate on all prepare writes in the
  2463		 * prep_queue, and reassemble those that share the same handle.
  2464		 * Once a handle has been reassembled, it is sent to the upper layers,
  2465		 * and the next handle is processed
  2466		 */
  2467		while (!sys_slist_is_empty(&chan->att->prep_queue)) {
  2468			struct bt_attr_data *data;
  2469			uint16_t handle;
  2470	
  2471			NET_BUF_SIMPLE_DEFINE_STATIC(reassembled_data,
  2472						     MIN(BT_ATT_MAX_ATTRIBUTE_LEN,
  2473							 CONFIG_BT_ATT_PREPARE_COUNT * BT_ATT_BUF_SIZE));
  2474	
  2475			buf = net_buf_slist_get(&chan->att->prep_queue);
  2476			data = net_buf_user_data(buf);
  2477			handle = data->handle;
  2478	
  2479			LOG_DBG("buf %p handle 0x%04x offset %u", buf, handle, data->offset);
  2480	
  2481			net_buf_simple_reset(&reassembled_data);
  2482			net_buf_simple_add_mem(&reassembled_data, buf->data, buf->len);
  2483	
  2484			err = exec_write_reassemble(handle, data->offset,
  2485						    &chan->att->prep_queue,
  2486						    &reassembled_data);
  2487			if (err != BT_ATT_ERR_SUCCESS) {
  2488				send_err_rsp(chan, BT_ATT_OP_EXEC_WRITE_REQ,
  2489					     handle, err);
  2490				return 0;
  2491			}
  2492	
  2493			/* Just discard the data if an error was set */
  2494			if (!err && flags == BT_ATT_FLAG_EXEC) {
  2495				err = att_write_rsp(chan, BT_ATT_OP_EXEC_WRITE_REQ, 0,
  2496						    handle, data->offset,
  2497						    reassembled_data.data,
  2498						    reassembled_data.len);
  2499				if (err) {
  2500					/* Respond here since handle is set */
  2501					send_err_rsp(chan, BT_ATT_OP_EXEC_WRITE_REQ,
  2502						     data->handle, err);
  2503				}
  2504			}
  2505	
  2506			net_buf_unref(buf);
  2507		}
  2508	
  2509		if (err) {
  2510			return 0;
  2511		}
  2512	
  2513		/* Generate response */
  2514		buf = bt_att_create_rsp_pdu(chan, BT_ATT_OP_EXEC_WRITE_RSP);
  2515		if (!buf) {
  2516			return BT_ATT_ERR_UNLIKELY;
  2517		}
  2518	
  2519		bt_att_chan_send_rsp(chan, buf);
  2520	
  2521		return 0;
  2522	}
