   122	/****************************************************************************
   123	 * Name: up_allocate_heap/up_allocate_kheap
   124	 *
   125	 * Description:
   126	 *   This function will be called to dynamically set aside the heap region.
   127	 *
   128	 *   - For the normal "flat" build, this function returns the size of the
   129	 *     single heap.
   130	 *   - For the protected build (CONFIG_BUILD_PROTECTED=y) with both kernel-
   131	 *     and user-space heaps (CONFIG_MM_KERNEL_HEAP=y), this function
   132	 *     provides the size of the unprotected, user-space heap.
   133	 *   - For the kernel build (CONFIG_BUILD_KERNEL=y), this function provides
   134	 *     the size of the protected, kernel-space heap.
   135	 *
   136	 *   If a protected kernel-space heap is provided, the kernel heap must be
   137	 *   allocated by an analogous up_allocate_kheap(). A custom version of this
   138	 *   file is needed if memory protection of the kernel heap is required.
   139	 *
   140	 *   The following memory map is assumed for the flat build:
   141	 *
   142	 *     .data region.  Size determined at link time.
   143	 *     .bss  region  Size determined at link time.
   144	 *     IDLE thread stack.  Size determined by CONFIG_IDLETHREAD_STACKSIZE.
   145	 *     Heap.  Extends to the end of SRAM.
   146	 *
   147	 *   The following memory map is assumed for the kernel build:
   148	 *
   149	 *     Kernel .data region.  Size determined at link time.
   150	 *     Kernel .bss  region  Size determined at link time.
   151	 *     Kernel IDLE thread stack.  Size determined by
   152	 *       CONFIG_IDLETHREAD_STACKSIZE.
   153	 *     Padding for alignment
   154	 *     User .data region.  Size determined at link time.
   155	 *     User .bss region  Size determined at link time.
   156	 *     Kernel heap.  Size determined by CONFIG_MM_KERNEL_HEAPSIZE.
   157	 *     User heap.  Extends to the end of SRAM.
   158	 *
   159	 ****************************************************************************/
   160	
   161	void up_allocate_heap(FAR void **heap_start, size_t *heap_size)
   162	{
   163	  /* The heap starts at g_idle_topstack and extends to the end of SRAM */
   164	  
   165	  *heap_start = (FAR void *)g_idle_topstack;
   166	  *heap_size  = SRAM_END - g_idle_topstack;
   167	}
