   259	static int meminfo_open(FAR struct file *filep, FAR const char *relpath,
   260	                        int oflags, mode_t mode)
   261	{
   262	  FAR struct meminfo_file_s *procfile;
   263	
   264	  finfo("Open '%s'\n", relpath);
   265	
   266	  /* Allocate a container to hold the file attributes */
   267	
   268	  procfile = fs_heap_zalloc(sizeof(struct meminfo_file_s));
   269	  if (!procfile)
   270	    {
   271	      ferr("ERROR: Failed to allocate file attributes\n");
   272	      return -ENOMEM;
   273	    }
   274	
   275	  /* Save the attributes as the open-specific state in filep->f_priv */
   276	
   277	  filep->f_priv = procfile;
   278	  return OK;
   279	}
