   281	/****************************************************************************
   282	 * Name: meminfo_close
   283	 ****************************************************************************/
   284	
   285	static int meminfo_close(FAR struct file *filep)
   286	{
   287	  FAR struct meminfo_file_s *procfile;
   288	
   289	  /* Recover our private data from the struct file instance */
   290	
   291	  procfile = (FAR struct meminfo_file_s *)filep->f_priv;
   292	  DEBUGASSERT(procfile);
   293	
   294	  /* Release the file attributes structure */
   295	
   296	  fs_heap_free(procfile);
   297	  filep->f_priv = NULL;
   298	  return OK;
   299	}
