  35	#define CHECK_ENABLED()                   \
  36	    {                                     \
  37	        if (!g_gatts_manager.started)     \
  38	            return BT_STATUS_NOT_ENABLED; \
  39	    }
  40	
  41	#define CHECK_SERVICE_VALID(_list, _srv)                                                       \
  42	    do {                                                                                       \
  43	        bt_list_node_t* _node;                                                                 \
  44	        if (!_srv)                                                                             \
  45	            return BT_STATUS_PARM_INVALID;                                                     \
  46	        for (_node = bt_list_head(_list); _node != NULL; _node = bt_list_next(_list, _node)) { \
  47	            if (bt_list_node(_node) == _srv)                                                   \
  48	                break;                                                                         \
  49	        }                                                                                      \
  50	        if (!_node)                                                                            \
  51	            return BT_STATUS_PARM_INVALID;                                                     \
  52	    } while (0)
  53	
  54	#define GATTS_CALLBACK_FOREACH(_cbsl, _type, _cback, args...)                                  \
  55	    do {                                                                                       \
  56	        bt_list_node_t* _node;                                                                 \
  57	        bt_list_t* _list = _cbsl;                                                              \
  58	        for (_node = bt_list_head(_list); _node != NULL; _node = bt_list_next(_list, _node)) { \
  59	            _type* _inst = (_type*)bt_list_node(_node);                                        \
  60	            if (_inst->callbacks && _inst->callbacks->_cback)                                  \
  61	                _inst->callbacks->_cback(_inst, args);                                         \
  62	        }                                                                                      \
  63	    } while (0)
