  65	/****************************************************************************
  66	 * Private Types
  67	 ****************************************************************************/
  68	
  69	typedef struct
  70	{
  71	    bool started;
  72	    pthread_mutex_t device_lock;
  73	    bt_list_t* services;
  74	    bt_list_t* pend_ops;
  75	
  76	} gatts_manager_t;
  77	
  78	typedef struct
  79	{
  80	    uint16_t start_handle;
  81	    uint16_t end_handle;
  82	    int element_size;
  83	    gatt_element_t elements[0];
  84	
  85	} service_table_t;
  86	
  87	typedef struct
  88	{
  89	    void* remote;
  90	    uint16_t srv_id;
  91	    pthread_mutex_t srv_lock;
  92	    void** user_phandle;
  93	    gatts_manager_t* manager;
  94	    gatts_callbacks_t* callbacks;
  95	    bt_list_t* tables;
  96	
  97	} gatts_service_t;
  98	
  99	/****************************************************************************
 100	 * Private Function Prototypes
 101	 ****************************************************************************/
 102	
 103	/****************************************************************************
 104	 * Private Data
 105	 ****************************************************************************/
 106	static gatts_manager_t g_gatts_manager = {
 107	    .started = false,
 108	    .services = NULL,
 109	    .pend_ops = NULL,
 110	};
 111	
 112	/****************************************************************************
 113	 * Private Functions
 114	 ****************************************************************************/
 115	
 116	static bool element_id_cmp(void* table, void* id)
 117	{
 118	    uint16_t f_handle = *(uint16_t*)id;
 119	    service_table_t* f_svc_table = (service_table_t*)table;
 120	    return (f_handle >= f_svc_table->start_handle && f_handle <= f_svc_table->end_handle);
 121	}
 122	
 123	static service_table_t* find_service_table_by_id(gatts_service_t* service, uint16_t element_id)
 124	{
 125	    return bt_list_find(service->tables, element_id_cmp, &element_id);
 126	}
 127	
 128	static gatt_element_t* find_service_element_by_id(gatts_service_t* service, uint16_t element_id)
 129	{
 130	    service_table_t* svc_table = find_service_table_by_id(service, element_id);
 131	    if (!svc_table)
 132	        return NULL;
 133	
 134	    gatt_element_t* element = svc_table->elements;
 135	    for (int i = 0; i < svc_table->element_size; i++, element++) {
 136	        if (element->handle == element_id)
 137	            return element;
 138	    }
 139	    return NULL;
 140	}
 141	
