    95	
    96	      q = uv__queue_head(&slow_io_pending_wq);
    97	      uv__queue_remove(q);
    98	      uv__queue_init(q);
    99	
   100	      /* If there is more slow I/O work, schedule it to be run as well. */
   101	      if (!uv__queue_empty(&slow_io_pending_wq)) {
   102	        uv__queue_insert_tail(&lwq, &run_slow_work_message);
   103	        if (idle_threads > 0)
   104	          uv_cond_signal(&cond);
   105	      }
   106	    }
   107	
   108	    uv_mutex_unlock(&mutex);
   109	
   110	    w = uv__queue_data(q, struct uv__work, wq);
   111	    w->work(w);
   112	
   113	    uv_mutex_lock(&w->loop->wq_mutex);
   114	    w->work = NULL;  /* Signal uv_cancel() that the work req is done
   115	                        executing. */
   116	    uv__queue_insert_tail(&w->loop->wq, &w->wq);
   117	    uv_async_send(&w->loop->wq_async);
   118	    uv_mutex_unlock(&w->loop->wq_mutex);
   119	
   120	    /* Lock `mutex` since that is expected at the start of the next
   121	     * iteration. */
   122	    uv_mutex_lock(&mutex);
   123	    if (is_slow_work) {
   124	      /* `slow_io_work_running` is protected by `mutex`. */
   125	      slow_io_work_running--;
   126	    }
   127	  }
   128	}
