   505	static void *probe_communication_thread(void *arg)
   506	{
   507	  struct probe_rx_slot_s slot;
   508	  bt_address_t peer_addr;
   509	  uint32_t generation;
   510	  uint32_t active_generation = 0;
   511	  bool connected;
   512	  bool have_slot;
   513	  int wait_status;
   514	
   515	  (void)arg;
   516	
   517	  for (;;)
   518	    {
   519	      do
   520	        {
   521	          wait_status = sem_wait(&g_rx_sem);
   522	        }
   523	      while (wait_status < 0 && errno == EINTR);
   524	
   525	      if (wait_status < 0)
   526	        {
   527	          continue;
   528	        }
   529	
   530	      pthread_mutex_lock(&g_state_lock);
   531	      generation = g_connection_generation;
   532	      connected = g_peer_connected;
   533	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
   534	      have_slot = g_rx_count > 0;
   535	      if (have_slot)
   536	        {
   537	          memcpy(&slot, &g_rx_queue[g_rx_tail], sizeof(slot));
   538	          g_rx_tail = (g_rx_tail + 1) % PROBE_RX_QUEUE_DEPTH;
   539	          g_rx_count--;
   540	        }
   541	      pthread_mutex_unlock(&g_state_lock);
   542	
   543	      if (generation != active_generation)
   544	        {
   545	          memset(&g_throughput, 0, sizeof(g_throughput));
   546	          active_generation = generation;
   547	        }
   548	
   549	      if (!have_slot)
   550	        {
   551	          continue;
   552	        }
   553	
   554	      if (!connected || slot.connection_generation != generation ||
   555	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
   556	        {
   557	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
   558	          continue;
   559	        }
   560	
   561	      probe_process_frame(g_service_handle, slot.value, slot.length);
   562	    }
   563	
   564	  return NULL;
   565	}
